* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #f0f4f8;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: #1e293b;
  padding: 16px;
}

.card {
  background: #ffffff;
  border-radius: 16px;
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.08);
  padding: 24px;
  width: 100%;
  max-width: 520px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  text-align: center;
  color: #0f172a;
}

.subtitle {
  text-align: center;
  color: #64748b;
  font-size: 1rem;
  margin-top: -8px;
}

.palette {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
  align-items: center;
}

.swatch {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  border: 3px solid transparent;
  cursor: pointer;
  transition: transform 0.1s, border-color 0.1s, box-shadow 0.1s;
  outline: none;
}

.swatch:hover {
  transform: scale(1.08);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.swatch:focus-visible {
  border-color: #0f172a;
  box-shadow: 0 0 0 3px rgba(15, 23, 42, 0.25);
}

.swatch[aria-pressed="true"] {
  border-color: #0f172a;
  box-shadow: 0 0 0 3px rgba(15, 23, 42, 0.25);
}

.swatch:active {
  transform: scale(0.95);
}

.eraser {
  padding: 10px 16px;
  border-radius: 10px;
  border: 2px solid #cbd5e1;
  background: #f8fafc;
  color: #1e293b;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
  outline: none;
}

.eraser:hover {
  background: #e2e8f0;
  border-color: #94a3b8;
}

.eraser:focus-visible {
  border-color: #0f172a;
  box-shadow: 0 0 0 3px rgba(15, 23, 42, 0.25);
}

.eraser[aria-pressed="true"] {
  background: #0f172a;
  color: #ffffff;
  border-color: #0f172a;
}

.eraser:active {
  transform: scale(0.96);
}

.grid {
  display: grid;
  grid-template-columns: repeat(16, 1fr);
  gap: 2px;
  aspect-ratio: 1 / 1;
  width: 100%;
  max-width: 480px;
  margin: 0 auto;
  background: #e2e8f0;
  padding: 2px;
  border-radius: 8px;
  outline: none;
}

.cell {
  background: #ffffff;
  border-radius: 3px;
  cursor: pointer;
  transition: background 0.1s;
  min-width: 0;
  min-height: 0;
  aspect-ratio: 1 / 1;
  border: none;
  padding: 0;
  outline: none;
}

.cell:hover {
  opacity: 0.8;
}

.cell:focus-visible {
  box-shadow: inset 0 0 0 2px #0f172a;
  z-index: 1;
}

.cell:active {
  opacity: 0.6;
}

.controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.clear-btn {
  padding: 12px 24px;
  border-radius: 10px;
  border: none;
  background: #e63946;
  color: #ffffff;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  outline: none;
}

.clear-btn:hover {
  background: #c1121f;
}

.clear-btn:focus-visible {
  box-shadow: 0 0 0 3px rgba(230, 57, 70, 0.4);
}

.clear-btn:active {
  transform: scale(0.96);
}

.counter {
  font-size: 1rem;
  color: #475569;
}

.counter span {
  font-weight: 700;
  color: #0f172a;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .swatch {
    width: 40px;
    height: 40px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .controls {
    flex-direction: column;
    align-items: stretch;
    text-align: center;
  }
  .counter {
    text-align: center;
  }
}

const grid = document.getElementById('grid');
const countEl = document.getElementById('count');
const clearBtn = document.getElementById('clear');
const eraserBtn = document.getElementById('eraser');
const swatches = document.querySelectorAll('.swatch');

let selectedColor = '#e63946';
let eraserActive = false;
let paintedCount = 0;

for (let i = 0; i < 256; i++) {
  const cell = document.createElement('button');
  cell.className = 'cell';
  cell.dataset.index = i;
  cell.setAttribute('aria-label', `Cell ${Math.floor(i / 16) + 1}, ${(i % 16) + 1}`);
  cell.addEventListener('click', () => paintCell(cell));
  grid.appendChild(cell);
}

function updateCount() {
  countEl.textContent = paintedCount;
}

function paintCell(cell) {
  const wasPainted = cell.dataset.painted === 'true';
  if (eraserActive) {
    cell.style.background = '#ffffff';
    cell.dataset.painted = 'false';
    if (wasPainted) paintedCount--;
  } else {
    cell.style.background = selectedColor;
    cell.dataset.painted = 'true';
    if (!wasPainted) paintedCount++;
  }
  updateCount();
}

function selectColor(color) {
  selectedColor = color;
  eraserActive = false;
  swatches.forEach(s => s.setAttribute('aria-pressed', s.dataset.color === color ? 'true' : 'false'));
  eraserBtn.setAttribute('aria-pressed', 'false');
}

swatches.forEach(swatch => {
  swatch.addEventListener('click', () => selectColor(swatch.dataset.color));
});

eraserBtn.addEventListener('click', () => {
  eraserActive = !eraserActive;
  eraserBtn.setAttribute('aria-pressed', eraserActive ? 'true' : 'false');
  if (eraserActive) {
    swatches.forEach(s => s.setAttribute('aria-pressed', 'false'));
  } else {
    selectColor(selectedColor);
  }
});

clearBtn.addEventListener('click', () => {
  document.querySelectorAll('.cell').forEach(cell => {
    cell.style.background = '#ffffff';
    cell.dataset.painted = 'false';
  });
  paintedCount = 0;
  updateCount();
});

// Initialize first swatch as selected
selectColor('#e63946');
updateCount();
